import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void identityPlainPayloadNumberAndRepeatedWrap(){for(int kind=0;kind<4;kind++){Object q=TaskBinding.create(kind,1);Object a=kind==0?new String("X"):kind==1?Integer.valueOf(1000):kind==2?TaskBinding.payload("X"):Double.valueOf(1.25);Object b=kind==0?new String("Y"):kind==1?Integer.valueOf(1001):kind==2?TaskBinding.payload("Y"):Integer.valueOf(2);TaskBinding.put(q,a);assertSame(a,TaskBinding.get(q));TaskBinding.put(q,b);assertSame(b,TaskBinding.get(q));assertFalse(capture(()->assertNull(TaskBinding.get(q))).isBlank());assertFalse(capture(()->assertNull(TaskBinding.get(q))).isBlank());}}@Test void growthWithElementsAcrossBoundary(){Object q=TaskBinding.create(0,2);TaskBinding.put(q,"A");TaskBinding.put(q,"B");assertEquals("A",TaskBinding.get(q));TaskBinding.put(q,"C");TaskBinding.put(q,"D");assertEquals("B",TaskBinding.get(q));assertEquals("C",TaskBinding.get(q));assertEquals("D",TaskBinding.get(q));for(int i=0;i<20;i++)TaskBinding.put(q,"V"+i);for(int i=0;i<20;i++)assertEquals("V"+i,TaskBinding.get(q));}}
